from pathlib import Path
root=Path(__file__).resolve().parents[1]
def replace_line(path,prefix,new):
 p=root/path;s=p.read_text(encoding='utf-8');lines=s.splitlines();matches=[i for i,line in enumerate(lines) if line.startswith(prefix)];assert len(matches)==1,(path,matches);lines[matches[0]]=new;p.write_bytes(('\n'.join(lines)+'\n').encode('utf-8'))
